/** An employee record held in the address book. Records are immutable; changes produce new objects. */
export interface Employee {
  /** Unique identifier, generated by the store. */
  readonly id: string;
  readonly firstName: string;
  readonly lastName: string;
  /** Free-text department name. */
  readonly department: string;
  /** Single contact phone number, as entered (digits, spaces, `+`, `(`, `)`, `-`). */
  readonly phoneNumber: string;
}

/** Data required to create an employee. The id is assigned by the store. */
export type NewEmployee = Omit<Employee, 'id'>;

/** A field of {@link Employee} that can fail validation. */
export type EmployeeField = keyof Employee;

/** Why a field failed validation. */
export type EmployeeValidationCode = 'required' | 'maxLength' | 'pattern';

/** A single validation failure. Holds no field values, so it is safe to log. */
export interface EmployeeValidationIssue {
  readonly field: EmployeeField;
  readonly code: EmployeeValidationCode;
}

/** Field rules shared by the domain model and the employee form. */
export const EMPLOYEE_CONSTRAINTS = {
  nameMaxLength: 50,
  departmentMaxLength: 100,
  phoneNumberMaxLength: 20,
  phoneNumberMinDigits: 6,
  phoneNumberMaxDigits: 15,
  /** Optional leading `+`, then digits, spaces, parentheses and hyphens. */
  phoneNumberPattern: /^\+?[\d\s()-]+$/,
} as const;

/** A field the user enters when creating an employee. */
export type NewEmployeeField = keyof NewEmployee;

/** Fields of {@link NewEmployee}, in form and validation order. */
export const NEW_EMPLOYEE_FIELDS = [
  'firstName',
  'lastName',
  'department',
  'phoneNumber',
] as const satisfies readonly NewEmployeeField[];

/** Maximum length of each field after trimming. */
export const EMPLOYEE_MAX_LENGTHS: Readonly<Record<NewEmployeeField, number>> = {
  firstName: EMPLOYEE_CONSTRAINTS.nameMaxLength,
  lastName: EMPLOYEE_CONSTRAINTS.nameMaxLength,
  department: EMPLOYEE_CONSTRAINTS.departmentMaxLength,
  phoneNumber: EMPLOYEE_CONSTRAINTS.phoneNumberMaxLength,
};

/** Direction for sorting employees by last name. */
export type SortDirection = 'asc' | 'desc';

/** Search and sort criteria for the employee list. */
export interface EmployeeFilter {
  /** Matches first name, last name or full name. Empty string means no name filter. */
  readonly name: string;
  /** Matches department, case-insensitively. Empty string means all departments. */
  readonly department: string;
  readonly sort: SortDirection;
}

/** Filter applied when the employee list first opens: everything, last name A→Z. */
export const DEFAULT_EMPLOYEE_FILTER: EmployeeFilter = {
  name: '',
  department: '',
  sort: 'asc',
};

/** Display name, e.g. "Priya Sharma". The single definition used for search, labels and messages. */
export function fullName(employee: Pick<Employee, 'firstName' | 'lastName'>): string {
  return `${employee.firstName} ${employee.lastName}`;
}

/** Thrown when employee data breaks the domain rules. The message lists fields only, never values. */
export class EmployeeValidationError extends Error {
  constructor(readonly issues: readonly EmployeeValidationIssue[]) {
    super(
      `Invalid employee: ${issues.map((issue) => `${issue.field} (${issue.code})`).join(', ')}`,
    );
    this.name = 'EmployeeValidationError';
  }
}

/**
 * Checks new-employee data against the domain rules.
 * Values are trimmed before checking. Returns an empty array when the data is valid.
 */
export function validateNewEmployee(input: NewEmployee): EmployeeValidationIssue[] {
  return NEW_EMPLOYEE_FIELDS.flatMap((field) => {
    const code = validateEmployeeField(field, input[field]);
    return code === null ? [] : [{ field, code }];
  });
}

/**
 * Checks one field against the domain rules. The value is trimmed before checking.
 * @returns The first rule the value breaks, or `null` when it is valid.
 */
export function validateEmployeeField(
  field: NewEmployeeField,
  value: string,
): EmployeeValidationCode | null {
  const trimmed = value.trim();
  if (trimmed === '') {
    return 'required';
  }
  if (trimmed.length > EMPLOYEE_MAX_LENGTHS[field]) {
    return 'maxLength';
  }
  if (field === 'phoneNumber' && !isValidPhoneNumber(trimmed)) {
    return 'pattern';
  }
  return null;
}

/**
 * Creates a validated, trimmed, frozen employee.
 * @throws {EmployeeValidationError} when the id is blank or the data breaks a domain rule.
 */
export function createEmployee(id: string, input: NewEmployee): Employee {
  const issues: EmployeeValidationIssue[] = [
    ...(id.trim() === '' ? [{ field: 'id', code: 'required' } as const] : []),
    ...validateNewEmployee(input),
  ];
  if (issues.length > 0) {
    throw new EmployeeValidationError(issues);
  }
  return Object.freeze({ id, ...normalizeNewEmployee(input) });
}

function normalizeNewEmployee(input: NewEmployee): NewEmployee {
  return {
    firstName: input.firstName.trim(),
    lastName: input.lastName.trim(),
    department: input.department.trim(),
    phoneNumber: input.phoneNumber.trim(),
  };
}

function isValidPhoneNumber(value: string): boolean {
  const digitCount = value.replace(/\D/g, '').length;
  return (
    EMPLOYEE_CONSTRAINTS.phoneNumberPattern.test(value) &&
    digitCount >= EMPLOYEE_CONSTRAINTS.phoneNumberMinDigits &&
    digitCount <= EMPLOYEE_CONSTRAINTS.phoneNumberMaxDigits
  );
}
